            return C

        def mat_pow(A, p):
            res = [[1 if i == j else 0 for j in range(26)] for i in range(26)]
            base = A
            while p > 0:
                if p & 1:
                    res = mat_mul(res, base)
                base = mat_mul(base, base)
                p >>= 1
            return res

