class Solution {
public:
    int lengthAfterTransformations(string s, int t, vector<int>& nums) {
        const long long MOD = 1000000007;
        using Matrix = vector<vector<long long>>;

        auto mat_mul = [&](const Matrix& A, const Matrix& B) {
            Matrix C(26, vector<long long>(26, 0));
            for (int i = 0; i < 26; ++i) {
                for (int k = 0; k < 26; ++k) {
                    if (!A[i][k]) continue;
                    for (int j = 0; j < 26; ++j) {
                        C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD;
                    }
                }
            }
            return C;
        };

        auto mat_pow = [&](Matrix A, int p) {
            Matrix res(26, vector<long long>(26, 0));
            for (int i = 0; i < 26; ++i) res[i][i] = 1;
            while (p > 0) {
                if (p & 1) res = mat_mul(res, A);
                A = mat_mul(A, A);
                p >>= 1;
            }
            return res;
        };

        Matrix M(26, vector<long long>(26, 0));
        for (int i = 0; i < 26; ++i) {
            for (int step = 1; step <= nums[i]; ++step) {
                int target = (i + step) % 26;
                M[i][target]++;
            }
        }

        Matrix Mt = mat_pow(M, t);
        vector<long long> initial(26, 0);
        for (char ch : s) initial[ch - 'a']++;

        long long ans = 0;
        for (int i = 0; i < 26; ++i) {
            if (initial[i]) {
                long long generated = 0;
                for (int j = 0; j < 26; ++j) generated = (generated + Mt[i][j]) % MOD;
                ans = (ans + initial[i] * generated) % MOD;
            }
        }
        return ans;
    }
};

class Solution {
    public int lengthAfterTransformations(String s, int t, List<Integer> nums) {
        long MOD = 1_000_000_007;
        long[][] M = new long[26][26];
        for (int i = 0; i < 26; i++) {
            int cnt = nums.get(i);
            for (int step = 1; step <= cnt; step++) {
                int target = (i + step) % 26;
                M[i][target]++;
            }
        }

        long[][] Mt = matPow(M, t, MOD);
        long[] initial = new long[26];
        for (int i = 0; i < s.length(); i++) {
            initial[s.charAt(i) - 'a']++;
        }

        long ans = 0;
        for (int i = 0; i < 26; i++) {
            if (initial[i] > 0) {
                long generated = 0;
                for (int j = 0; j < 26; j++) {
                    generated = (generated + Mt[i][j]) % MOD;
                }
                ans = (ans + initial[i] * generated) % MOD;
            }
        }
        return (int) ans;
    }

    private long[][] matMul(long[][] A, long[][] B, long MOD) {
        long[][] C = new long[26][26];
        for (int i = 0; i < 26; i++) {
            for (int k = 0; k < 26; k++) {
                if (A[i][k] != 0) {
                    for (int j = 0; j < 26; j++) {
                        C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD;
                    }
                }
            }
        }
        return C;
    }

    private long[][] matPow(long[][] A, int p, long MOD) {
        long[][] res = new long[26][26];
        for (int i = 0; i < 26; i++) res[i][i] = 1;
        long[][] base = A;
        while (p > 0) {
            if ((p & 1) == 1) res = matMul(res, base, MOD);
            base = matMul(base, base, MOD);
            p >>= 1;
        }
        return res;
    }
}

var lengthAfterTransformations = function(s, t, nums) {
    const MOD = 1000000007n;
    function matMul(A, B) {
        const C = Array.from({ length: 26 }, () => new Array(26).fill(0n));
        for (let i = 0; i < 26; i++) {
            for (let k = 0; k < 26; k++) {
                if (A[i][k] !== 0n) {
                    for (let j = 0; j < 26; j++) {
                        C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD;
                    }
                }
            }
        }
        return C;
    }

    function matPow(A, p) {
        let res = Array.from({ length: 26 }, (_, i) => {
            const row = new Array(26).fill(0n);
            row[i] = 1n;
            return row;
        });
        let base = A;
        while (p > 0) {
            if (p & 1) res = matMul(res, base);
            base = matMul(base, base);
            p >>= 1;
        }
        return res;
    }

    const M = Array.from({ length: 26 }, () => new Array(26).fill(0n));
    for (let i = 0; i < 26; i++) {
        for (let step = 1; step <= nums[i]; step++) {
            const target = (i + step) % 26;
            M[i][target] += 1n;
        }
    }

    const Mt = matPow(M, t);
    const initial = new Array(26).fill(0n);
    for (let i = 0; i < s.length; i++) {
        initial[s.charCodeAt(i) - 97] += 1n;
    }

    let ans = 0n;
    for (let i = 0; i < 26; i++) {
        if (initial[i] > 0n) {
            let generated = 0n;
            for (let j = 0; j < 26; j++) {
                generated = (generated + Mt[i][j]) % MOD;
            }
            ans = (ans + initial[i] * generated) % MOD;
        }
    }
    return Number(ans);
};
